from pathlib import Path
import subprocess
import base64

BASE = "c3097cb"

def run(args):
    return subprocess.run(
        args,
        check=True,
        capture_output=True,
        text=True,
        encoding="utf-8",
    )

head = run(["git", "rev-parse", "--short", "HEAD"]).stdout.strip()

if not head.startswith(BASE):
    raise SystemExit(
        f"This patch requires HEAD {BASE}, but HEAD is {head}. "
        "No files were changed."
    )

layout_path = Path("app/(portal)/layout.tsx")
css_path = Path("components/sepulchria/sep-ui-unified.css")
layer_path = Path("components/portal/portal-interaction-layer.tsx")

if not layout_path.exists():
    raise SystemExit("Missing app/(portal)/layout.tsx")

if not css_path.exists():
    raise SystemExit("Missing components/sepulchria/sep-ui-unified.css")

layout = layout_path.read_text(encoding="utf-8")
css = css_path.read_text(encoding="utf-8")

layer_source = base64.b64decode('').decode("utf-8")
interaction_css = base64.b64decode('').decode("utf-8")

import_anchor = 'import { PortalHeader } from "@/components/portal/portal-header";\n'
import_line = 'import { PortalInteractionLayer } from "@/components/portal/portal-interaction-layer";\n'

if import_line not in layout:
    if import_anchor not in layout:
        raise SystemExit(
            "PortalHeader import anchor not found. No files were changed."
        )
    layout = layout.replace(
        import_anchor,
        import_anchor + import_line,
        1,
    )

mount_anchor = """            <PortalSessionGuard />


            <div className="shrink-0">"""

mount_new = """            <PortalSessionGuard />

            <PortalInteractionLayer />

            <div className="shrink-0">"""

if "<PortalInteractionLayer />" not in layout:
    if mount_anchor not in layout:
        raise SystemExit(
            "PortalSessionGuard mount anchor not found. No files were changed."
        )
    layout = layout.replace(
        mount_anchor,
        mount_new,
        1,
    )

css_marker = "SEPULCHRIA INTERACTIVE SURFACES — POINTER LIGHT + DEPTH"

if css_marker not in css:
    css += interaction_css

layer_path.write_text(
    layer_source,
    encoding="utf-8",
)

layout_path.write_text(
    layout,
    encoding="utf-8",
)

css_path.write_text(
    css,
    encoding="utf-8",
)

print("SUCCESS")
print("")
print("Added one shared Sepulchria interactive-surface system.")
print("")
print("Automatically covered:")
print("  - Shape / Feat / Character-style article cards")
print("  - framed Item / Ancestry / Association / Order / admin card-like surfaces")
print("  - Game / Forum / Messages / admin context buttons and links")
print("  - all enabled portal buttons")
print("  - left sidebar navigation links/buttons")
print("  - dynamically rendered portal content and portal iframe pages")
print("")
print("Interaction strengths:")
print("  card    = lift + subtle pointer tilt + moving illumination")
print("  row     = reduced movement + moving illumination")
print("  control = small pop + illumination")
print("  nav     = very small pop + illumination")
print("")
print("Existing skin colours, borders and component shadows remain authoritative.")
print("Reduced-motion users keep illumination without physical movement.")
print("")
print("Changed:")
print("  app/(portal)/layout.tsx")
print("  components/sepulchria/sep-ui-unified.css")
print("Created:")
print("  components/portal/portal-interaction-layer.tsx")
print("")
print("Run: npm run build")
